const input = $input.all()[0]?.json || {};
// niche comes as direct field from Execute Workflow Trigger
const niche = input.niche || input.category || 'fitness';
return [{ json: { niche } }];

const niche = $('Unpack Input').first().json.niche;
const shopRaw = $('Sticker Google Search').first()?.json || {};

const results = shopRaw?.shopping_results || [];

// Extract price signals
const prices = results.map(r => parseFloat((r.price || '').replace(/[^0-9.]/g, ''))).filter(p => p > 0);
const avgPrice = prices.length ? (prices.reduce((s,p) => s+p, 0) / prices.length).toFixed(2) : null;

// Top titles as inspiration seeds
const inspirationSeeds = results.slice(0, 10).map(r => r.title).filter(Boolean);

// Extract keywords from titles (all meaningful words)
const stopWords = new Set(['sticker','stickers','the','a','an','for','of','and','or','in','on','with','by','to','is','at','it','its','be','as','this','that','are','was','were','been','from']);
const allWords = results
  .flatMap(r => (r.title || '').toLowerCase().split(/[\s\-\/,.|&]+/))
  .filter(w => w.length > 3 && !stopWords.has(w));

// Frequency count
const freq = {};
allWords.forEach(w => { freq[w] = (freq[w] || 0) + 1; });
const topWords = Object.entries(freq).sort((a,b) => b[1]-a[1]).slice(0, 20).map(([w]) => w);

// Categorize by type
const colorTerms = ['black','white','red','blue','green','yellow','pink','purple','orange','gold','silver','neon','pastel','rainbow','bright','dark','colorful'];
const styleTerms = ['minimalist','vintage','retro','bold','cute','funny','aesthetic','cartoon','kawaii','floral','geometric','abstract','watercolor','flat','typographic','hand-drawn','grunge','boho'];
const iconTerms  = ['skull','heart','star','moon','sun','flower','leaf','wave','mountain','cat','dog','mushroom','ghost','lightning','crown','diamond','butterfly','dumbbell','weights','yoga','running','gym'];

const colors = topWords.filter(w => colorTerms.some(c => w.includes(c)));
const styles = topWords.filter(w => styleTerms.some(s => w.includes(s)));
const iconThemes = topWords.filter(w => iconTerms.some(i => w.includes(i)));

// Also scan full titles for these terms
const fullText = results.map(r => r.title || '').join(' ').toLowerCase();
const scanFor = (terms) => [...new Set(terms.filter(t => fullText.includes(t)))];

return [{ json: {
  source: 'stickers',
  niche,
  data: {
    colors:           scanFor(colorTerms).slice(0, 8),
    styles:           scanFor(styleTerms).slice(0, 8),
    iconThemes:       scanFor(iconTerms).slice(0, 8),
    topKeywords:      topWords.slice(0, 15),
    inspirationSeeds,
    avgStickerPrice:  avgPrice,
    totalResults:     results.length,
    legalNote:        'Style signals from public metadata only'
  }
} }];

const signals = $('Parse Sticker Signals').first()?.json || {};
const raw = $input.first().json?.choices?.[0]?.message?.content || '[]';
const clean = raw.replace(/```json|```/g, '').trim();
const match = clean.match(/\[[\s\S]*\]/);
let concepts = [];
try { concepts = JSON.parse(match?.[0] || '[]'); } catch(_) {}

return [{ json: {
  source: 'stickers',
  niche: signals.niche || '',
  data: {
    colors:            (signals.data?.colors || []),
    styles:            (signals.data?.styles || []),
    iconThemes:        (signals.data?.iconThemes || []),
    inspirationSeeds:  (signals.data?.inspirationSeeds || []),
    avgStickerPrice:   signals.data?.avgStickerPrice || null,
    totalResults:      signals.data?.totalResults || 0,
    originalConcepts:  concepts,
    legalNote: 'Style signals from public metadata only'
  }
} }];
